net.coobird.thumbnailator.filters.ImageFilter filter = new net.coobird.thumbnailator.filters.Colorize(java.awt.Color.RED, 0.5f);
java.awt.image.BufferedImage result = filter.apply(sourceImage);

assert result != null : "Resulting image should not be null";
assert result != sourceImage : "Colorize should return a new image instance, not mutate in place";
assert result.getWidth() == sourceImage.getWidth() : "Width should match original";
assert result.getHeight() == sourceImage.getHeight() : "Height should match original";

int diffCount = 0;
for (int y = 0; y < sourceImage.getHeight(); y++) {
    for (int x = 0; x < sourceImage.getWidth(); x++) {
        if (sourceImage.getRGB(x, y) != result.getRGB(x, y)) {
            diffCount++;
        }
    }
}

assert diffCount > 0 : "Image should be tinted and thus have different pixel values from the original";

System.out.println("__CHECK__ Colorize " + result.getWidth() + "x" + result.getHeight() + " diffCount=" + diffCount);

